const data = $input.first().json.choices?.[0]?.message?.content;

function safeMatch(regex, str) {
  const result = str ? str.match(regex) : null;
  return result ? result[1] : "Not specified";
}

if (!data) {
  return [{ json: { error: "No data found" } }];
}

// Extract fields using regex
const companyName           = safeMatch(/"Company_name":\s*"([^"]+)"/i, data);
const about                 = safeMatch(/"What_is_this_about":\s*"([^"]+)"/i, data);
const incidentDetails       = safeMatch(/"What Happened\?":\s*"([^"]+)"/i, data);
const impactedInfo          = safeMatch(/"What Information Was Impacted":\s*"([^"\n]+)"/i, data);
const impactedInfoArray         = safeMatch(/"What Information Was Impacted Array"\s*:\s*\[([^\]]+)\]/i, data);
const companyDescription    = safeMatch(/"About_Company":\s*"([^"]+)"/i, data);
const industry              = safeMatch(/"Industry":\s*"([^"]+)"/i, data);
const sinceDate             = safeMatch(/"since_date":\s*"([^"]+)"/i, data);
const campaignName          = safeMatch(/"campaign_name":\s*"([^"]+)"/i, data);
const leadType              = safeMatch(/"lead_type":\s*"([^"]+)"/i, data);

// Structure output
const scrapedData = {
  company_name: companyName,
  what_is_this_about: about,
  what_happened: incidentDetails,
  what_information_was_impacted: impactedInfo,
  what_information_was_impacted_array: impactedInfoArray,
  about_company: companyDescription,
  industry: industry,
  since_date: sinceDate,
  campaign_name: campaignName,
  lead_type: leadType
};

return [{ json: scrapedData }];

