  let raw = $json.body?.notice_link ?? $json.notice_link ?? 'na';
  if (raw == null) return 'na';
  if (Array.isArray(raw)) raw = raw[0] || 'na';
  raw = String(raw).trim();
  if (!raw || raw === 'na') return 'na';
  const stripped = raw.replace(/^[\{\[]+|[\}\]]+$/g, '');
  const parts = stripped.split(/[,;\s]+/).map(s => s.trim()).filter(Boolean);
  const urls = parts.filter(s => /^https?:\/\//i.test(s));
  if (!urls.length) return 'na';
  const gov = urls.find(u => /\.gov(\b|\/|:)/i.test(u));
  return gov || urls[0];
})() }}

={{ (() => {
  let raw = $json.body?.site_url ?? $json.site_url ?? '';
  if (raw == null) return '';
  if (Array.isArray(raw)) raw = raw[0] || '';
  raw = String(raw).trim();
  if (!raw) return '';
  const stripped = raw.replace(/^[\{\[]+|[\}\]]+$/g, '');
  const parts = stripped.split(/[,;\s]+/).map(s => s.trim()).filter(Boolean);
  const urls = parts.filter(s => /^https?:\/\//i.test(s));
  if (!urls.length) return '';
  return urls[0];
})() }}

